<?php declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/csrf.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/refunds.php';$current=tuman_require_role('TEACHER');$db=tuman_database();$students=tuman_teacher_students($db,$current['id']);$v=['assignment_id'=>'','currency_code'=>'INR','payment_date'=>gmdate('Y-m-d'),'amount'=>'','payment_method'=>'BANK_TRANSFER','reference_number'=>'','reason'=>''];$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){foreach($v as $k=>$x)$v[$k]=trim((string)($_POST[$k]??''));try{if(!tuman_csrf_is_valid($_POST['csrf_token']??null))throw new InvalidArgumentException('Your request could not be verified.');$id=filter_var($v['assignment_id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id)throw new InvalidArgumentException('Choose a student.');tuman_record_adjustment_refund($db,$current['id'],(int)$id,$v);header('Location: /Tuman/teacher/payments.php');exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}}tuman_teacher_page_start('Record other refund');?><h1>Record other refund</h1><p>Use this for a refund not linked to a recorded payment or unused credit. It remains in the transaction history and does not change an invoice balance.</p><?php if($error):?><p role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(tuman_csrf_token(),ENT_QUOTES,'UTF-8')?>"><p><label>Student <select name="assignment_id" required><option value="">Choose student</option><?php foreach($students as $s):?><option value="<?=(int)$s['assignment_id']?>"<?=$v['assignment_id']==$s['assignment_id']?' selected':''?>><?=htmlspecialchars(trim($s['first_name'].' '.($s['last_name']??'')),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><label>Currency <select name="currency_code"><?php foreach(TUMAN_CURRENCIES as $code=>$label):?><option value="<?=$code?>"<?=$code===$v['currency_code']?' selected':''?>><?=htmlspecialchars($code.' — '.$label,ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><label>Refund date <input type="date" name="payment_date" required value="<?=htmlspecialchars($v['payment_date'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Amount <input name="amount" inputmode="decimal" required value="<?=htmlspecialchars($v['amount'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Method <select name="payment_method"><?php foreach(TUMAN_PAYMENT_METHODS as $m):?><option value="<?=$m?>"<?=$m===$v['payment_method']?' selected':''?>><?=htmlspecialchars(str_replace('_',' ',$m),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><label>Reference <input name="reference_number" value="<?=htmlspecialchars($v['reference_number'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Reason <textarea name="reason" required><?=htmlspecialchars($v['reason'],ENT_QUOTES,'UTF-8')?></textarea></label></p><p><button>Record refund</button> <a href="/Tuman/teacher/payments.php">Cancel</a></p></form><?php tuman_teacher_page_end();?>
